# Find frame dimensions properly
def find_frame_bounds(grid, color):
    rows = set()
    cols = set()
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == color:
                rows.add(r)
                cols.add(c)
    return min(rows), max(rows), min(cols), max(cols)

